def give_built_in_pms_members_edit(apps, schema_editor):
    """Project Managers may switch their team members between Member and Guest (Employees and members › Edit = Team),
    in existing workspaces too. Roles that already have an Employees and members edit permission are left alone."""
    Role = apps.get_model("db", "Role")
    RolePermission = apps.get_model("db", "RolePermission")
    for role in Role.objects.filter(key="pm", deleted_at__isnull=True):
        if RolePermission.objects.filter(role=role, module="members", action="edit", deleted_at__isnull=True).exists():
            continue
        RolePermission.objects.create(role_id=role.id, module="members", action="edit", scope="team")


